if(isset($_GET['logout'])){session_destroy();header('Location: ?');exit;}
if(!isset($_SESSION['auth'])){if(isset($_POST['u'])&&isset($_POST['p'])){if($_POST['u']===$username&&$_POST['p']===$password){$_SESSION['auth']=true;header('Location: ?');exit;}else{$error='Invalid credentials';}}?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Console Login</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{background:#FF6B6B;font-family:'Courier New',monospace;display:flex;justify-content:center;align-items:center;height:100vh;border:4px solid #000;}.login-box{background:#FFE66D;border:4px solid #000;padding:40px;box-shadow:8px 8px 0 #000;max-width:400px;width:90%;}h1{font-size:28px;margin-bottom:20px;text-transform:uppercase;letter-spacing:2px;border-bottom:4px solid #000;padding-bottom:10px;}input{width:100%;padding:12px;margin:10px 0;border:3px solid #000;font-family:inherit;font-size:16px;background:#fff;box-shadow:4px 4px 0 #000;}button{width:100%;padding:15px;background:#4ECDC4;border:3px solid #000;font-family:inherit;font-size:18px;font-weight:bold;cursor:pointer;box-shadow:4px 4px 0 #000;text-transform:uppercase;margin-top:10px;}button:hover{transform:translate(2px,2px);box-shadow:2px 2px 0 #000;}button:active{transform:translate(4px,4px);box-shadow:0 0 0 #000;}.error{background:#FF6B6B;border:3px solid #000;padding:10px;margin-bottom:15px;font-weight:bold;}</style></head><body><div class="login-box"><h1>> CONSOLE_</h1><?php if(isset($error)):?><div class="error">! <?php echo htmlspecialchars($error);?></div><?php endif;?><form method="POST"><input type="text" name="u" placeholder="Username" required autofocus><input type="password" name="p" placeholder="Password" required><button type="submit">LOGIN</button></form></div></body></html><?php exit;}
function isWritable($path,$basePath,$allowed){$real=realpath($path);if($real===false){return false;}if(strpos($real,$basePath)!==0){return false;}$rel=substr($real,strlen($basePath)+1);if(empty($rel)||$rel==='.'){return false;}foreach($allowed as $a){if($rel===$a||strpos($rel,$a.'/')===0||strpos($rel,$a)===0){return true;}}return false;}
function getDirSize($dir){$size=0;foreach(glob(rtrim($dir,'/').'/*',GLOB_NOSORT) as $each){$size+=is_file($each)?filesize($each):getDirSize($each);}return $size;}
function formatSize($bytes){return $bytes>1024*1024*1024?round($bytes/1024/1024/1024,2).' GB':($bytes>1024*1024?round($bytes/1024/1024,2).' MB':round($bytes/1024,2).' KB');}
$currentDir=isset($_GET['dir'])?$_GET['dir']:'';$fullPath=realpath($basePath.($currentDir?'/'.$currentDir:''));
if($fullPath===false||strpos($fullPath,$basePath)!==0){$fullPath=$basePath;$currentDir='';}
$message='';$error='';
if(isset($_POST['action'])){switch($_POST['action']){case 'upload':if(!isWritable($fullPath,$basePath,$allowedWritable)){$error='Permission Denied: Cannot upload to this directory';}elseif(isset($_FILES['file'])){$file=$_FILES['file'];if($file['size']>$uploadMaxSize){$error='File too large (Max 3GB)';}else{$dest=$fullPath.'/'.basename($file['name']);if(move_uploaded_file($file['tmp_name'],$dest)){$message='File uploaded: '.basename($file['name']);}else{$error='Upload failed';}}}break;case 'mkdir':if(!isWritable($fullPath,$basePath,$allowedWritable)){$error='Permission Denied';}else{$name=preg_replace('/[^a-zA-Z0-9_\-\.]/','',$_POST['name']??'');if($name&&mkdir($fullPath.'/'.$name)){$message='Folder created: '.$name;}else{$error='Failed to create folder';}}break;case 'mkfile':if(!isWritable($fullPath,$basePath,$allowedWritable)){$error='Permission Denied';}else{$name=preg_replace('/[^a-zA-Z0-9_\-\.]/','',$_POST['name']??'');if($name&&file_put_contents($fullPath.'/'.$name,'')!==false){$message='File created: '.$name;}else{$error='Failed to create file';}}break;case 'delete':$target=$_POST['target']??'';$targetPath=realpath($basePath.($currentDir?'/'.$currentDir:'').'/'.basename($target));if($targetPath===false||strpos($targetPath,$basePath)!==0){$error='Invalid path';}elseif(!isWritable(dirname($targetPath),$basePath,$allowedWritable)){$error='Permission Denied';}else{if(is_dir($targetPath)){array_map('unlink',glob($targetPath.'/*'));@rmdir($targetPath);$message='Folder deleted';}elseif(is_file($targetPath)){unlink($targetPath);$message='File deleted';}else{$error='Target not found';}}break;case 'rename':$old=$_POST['old']??'';$new=preg_replace('/[^a-zA-Z0-9_\-\.]/','',$_POST['new']??'');if(!$new){$error='Invalid new name';break;}$oldPath=realpath($basePath.($currentDir?'/'.$currentDir:'').'/'.basename($old));if($oldPath===false||strpos($oldPath,$basePath)!==0){$error='Invalid path';break;}if(!isWritable(dirname($oldPath),$basePath,$allowedWritable)){$error='Permission Denied';break;}$newPath=dirname($oldPath).'/'.$new;if(rename($oldPath,$newPath)){$message='Renamed successfully';}else{$error='Rename failed';}break;case 'savefile':$target=$_POST['target']??'';$targetPath=realpath($basePath.($currentDir?'/'.$currentDir:'').'/'.basename($target));if($targetPath===false||strpos($targetPath,$basePath)!==0){$error='Invalid path';break;}if(!isWritable(dirname($targetPath),$basePath,$allowedWritable)){$error='Permission Denied';break;}if(file_put_contents($targetPath,$_POST['content']??'')!==false){$message='File saved';}else{$error='Save failed';}break;case 'unzip':if(!extension_loaded('zip')){$error='ZIP extension not available';break;}$target=$_POST['file']??'';$targetPath=realpath($basePath.($currentDir?'/'.$currentDir:'').'/'.basename($target));if($targetPath===false||strpos($targetPath,$basePath)!==0){$error='Invalid path';break;}if(!isWritable($fullPath,$basePath,$allowedWritable)){$error='Permission Denied';break;}$zip=new ZipArchive();if($zip->open($targetPath)===true){$totalSize=0;for($i=0;$i<$zip->numFiles;$i++){$stat=$zip->statIndex($i);$totalSize+=$stat['comp_size'];}if($totalSize>9*1024*1024*1024){$error='Extract would exceed 9GB limit (Anti-Zip Bomb)';break;}$zip->extractTo($fullPath);$zip->close();$message='Archive extracted';}else{$error='Failed to open archive';}break;}}
if(isset($_GET['download'])){$target=$_GET['download']??'';$targetPath=realpath($basePath.($currentDir?'/'.$currentDir:'').'/'.basename($target));if($targetPath===false||strpos($targetPath,$basePath)!==0){exit('Invalid path');}if(!is_file($targetPath)){exit('File not found');}header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.basename($targetPath).'"');header('Content-Length: '.filesize($targetPath));readfile($targetPath);exit;}
if(isset($_GET['edit'])){$target=$_GET['edit']??'';$targetPath=realpath($basePath.($currentDir?'/'.$currentDir:'').'/'.basename($target));if($targetPath===false||strpos($targetPath,$basePath)!==0){exit('Invalid path');}if(!is_file($targetPath)){exit('File not found');}$content=file_get_contents($targetPath);$lines=count(explode("\n",$content));?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Edit - <?php echo htmlspecialchars(basename($targetPath));?></title><style>*{margin:0;padding:0;box-sizing:border-box;}body{background:#2a2a2a;color:#fff;font-family:monospace;padding:20px;}textarea{width:100%;padding:15px;background:#1e1e1e;color:#00ff00;border:2px solid #444;font-family:monospace;font-size:14px;min-height:400px;resize:vertical;}button{padding:10px 20px;background:#4ECDC4;border:2px solid #000;font-weight:bold;cursor:pointer;margin-right:10px;margin-top:10px;}.btn-save{background:#7ED321;}.btn-back{background:#FF6B6B;}.editor-header{margin-bottom:20px;}a{color:#4ECDC4;text-decoration:none;}</style></head><body><div class="editor-header"><h1><?php echo htmlspecialchars(basename($targetPath));?></h1><p><?php echo number_format(strlen($content));?> bytes | <?php echo $lines;?> lines</p></div><form method="POST"><input type="hidden" name="action" value="savefile"><input type="hidden" name="target" value="<?php echo htmlspecialchars($target);?>"><textarea name="content" required><?php echo htmlspecialchars($content);?></textarea><br><button type="submit" class="btn-save">SAVE</button><a href="?dir=<?php echo urlencode($currentDir);?>"><button type="button" class="btn-back">BACK</button></a></form></body></html><?php exit;}
?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Console</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{background:#1a1a1a;color:#fff;font-family:monospace;padding:20px;}.header{background:#000;border:3px solid #fff;padding:20px;margin-bottom:20px;display:flex;justify-content:space-between;align-items:center;}.header h1{text-transform:uppercase;letter-spacing:2px;font-size:24px;}.status{background:#FFE66D;color:#000;padding:10px 15px;border:2px solid #000;font-weight:bold;}.message{background:#7ED321;border:3px solid #000;padding:15px;margin:10px 0;font-weight:bold;color:#000;}.error{background:#FF6B6B;border:3px solid #000;padding:15px;margin:10px 0;font-weight:bold;color:#000;}.breadcrumb{background:#2a2a2a;padding:15px;border:2px solid #444;margin-bottom:20px;}.breadcrumb a{color:#4ECDC4;text-decoration:none;margin:0 5px;}.breadcrumb a:hover{text-decoration:underline;}.controls{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-bottom:20px;}.btn{padding:12px;background:#4ECDC4;border:3px solid #000;font-family:monospace;font-weight:bold;cursor:pointer;text-transform:uppercase;text-decoration:none;display:inline-block;text-align:center;transition:all 0.2s;}.btn:hover{transform:translate(2px,2px);box-shadow:4px 4px 0 #000;}.btn-danger{background:#FF6B6B;}.btn-success{background:#7ED321;color:#000;}.drop-zone{border:3px dashed #4ECDC4;padding:40px;text-align:center;cursor:pointer;background:#2a2a2a;margin-bottom:20px;transition:all 0.3s;}.drop-zone.dragover{background:#4ECDC4;color:#000;}.drop-zone p{margin-bottom:10px;}.files{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:15px;}.file-item{background:#2a2a2a;border:2px solid #444;padding:15px;display:flex;flex-direction:column;}.file-item-name{font-weight:bold;margin-bottom:10px;word-break:break-all;}.file-item-info{font-size:12px;color:#aaa;margin-bottom:10px;}.file-item-actions{display:flex;gap:5px;flex-wrap:wrap;}.btn-small{padding:6px 10px;font-size:11px;background:#4ECDC4;border:2px solid #000;cursor:pointer;flex:1;min-width:50px;}.btn-small.btn-del{background:#FF6B6B;}.btn-small.btn-edit{background:#FFE66D;color:#000;}.btn-small.btn-dl{background:#7ED321;color:#000;}.btn-small.btn-disabled{background:#666;cursor:not-allowed;}.modal{display:none;position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.8);justify-content:center;align-items:center;z-index:1000;}.modal-content{background:#2a2a2a;border:3px solid #fff;padding:30px;max-width:400px;width:90%;}.modal-content h3{margin-bottom:15px;text-transform:uppercase;}.modal-content input{width:100%;padding:10px;margin-bottom:15px;background:#1a1a1a;border:2px solid #444;color:#fff;font-family:monospace;}.modal-content button{width:100%;padding:10px;margin-bottom:10px;}.progress-bar{display:none;width:100%;height:20px;background:#444;border:2px solid #fff;margin:15px 0;overflow:hidden;}.progress-fill{height:100%;background:#7ED321;width:0%;transition:width 0.2s;}</style></head><body><div class="header"><h1>> CONSOLE_</h1><div><a href="?logout=1" class="status" style="text-decoration:none;cursor:pointer;">LOGOUT</a></div></div><?php if(!empty($message)):?><div class="message">✓ <?php echo htmlspecialchars($message);?></div><?php endif;?><?php if(!empty($error)):?><div class="error">✗ <?php echo htmlspecialchars($error);?></div><?php endif;?><div class="breadcrumb">Location: <a href="?" style="color:#fff;font-weight:bold;">/mcserver</a><?php if($currentDir){foreach(explode('/',$currentDir) as $i=>$part){$path=implode('/',array_slice(explode('/',$currentDir),0,$i+1));echo ' / <a href="?dir='.urlencode($path).'">'.htmlspecialchars($part).'</a>';}}?></div><div class="controls"><button class="btn btn-success" onclick="showModal('folder')">+ FOLDER</button><button class="btn btn-success" onclick="showModal('file')">+ FILE</button></div><div class="drop-zone" id="dropZone"><p>📥 Drag & drop files here to upload</p><p style="font-size:12px;color:#aaa;">Max size: 3GB</p><input type="file" id="fileInput" style="display:none;"><div class="progress-bar" id="progressBar"><div class="progress-fill" id="progressFill"></div></div></div><?php $dirs=[];$files=[];if($handle=opendir($fullPath)){while(($f=readdir($handle))!==false){if($f==='.'||$f==='..') continue;if(is_dir($fullPath.'/'.$f)) $dirs[]=$f;else $files[]=$f;}closedir($handle);}sort($dirs);sort($files);if(empty($dirs)&&empty($files)):?><div style="text-align:center;padding:40px;color:#aaa;">Empty directory</div><?php else:?><div class="files"><?php foreach($dirs as $dir){$path=$currentDir?$currentDir.'/'.$dir:$dir;$fullDirPath=$fullPath.'/'.$dir;$dirWritable=isWritable($fullDirPath,$basePath,$allowedWritable);?><div class="file-item"><div class="file-item-name">📁 <?php echo htmlspecialchars($dir);?>/</div><div class="file-item-info">Folder</div><div class="file-item-actions"><a href="?dir=<?php echo urlencode($path);?>" class="btn-small">OPEN</a><?php if($dirWritable):?><form method="POST" style="display:inline;flex:1;" onsubmit="return confirm('Delete <?php echo htmlspecialchars($dir);?>?');"><input type="hidden" name="action" value="delete"><input type="hidden" name="target" value="<?php echo htmlspecialchars($path);?>"><button type="submit" class="btn-small btn-del">DEL</button></form><button class="btn-small" onclick="renameItem('<?php echo htmlspecialchars($path);?>','<?php echo htmlspecialchars($dir);?>')">REN</button><?php else:?><button class="btn-small btn-disabled" title="Permission Denied">LOCKED</button><?php endif;?></div></div><?php }foreach($files as $file){$path=$currentDir?$currentDir.'/'.$file:$file;$fullFilePath=$fullPath.'/'.$file;$fileWritable=isWritable($fullFilePath,$basePath,$allowedWritable);$size=filesize($fullFilePath);$sizeStr=formatSize($size);$ext=strtolower(pathinfo($file,PATHINFO_EXTENSION));$isZip=$ext==='zip';?><div class="file-item"><div class="file-item-name"><?php echo $isZip?'📦':'📄';?> <?php echo htmlspecialchars($file);?></div><div class="file-item-info"><?php echo $sizeStr;?></div><div class="file-item-actions"><a href="?edit=<?php echo urlencode($path);?>" class="btn-small btn-edit">EDIT</a><a href="?download=<?php echo urlencode($path);?>" class="btn-small btn-dl">DL</a><?php if($fileWritable):?><form method="POST" style="display:inline;flex:1;" onsubmit="return confirm('Delete <?php echo htmlspecialchars($file);?>?');"><input type="hidden" name="action" value="delete"><input type="hidden" name="target" value="<?php echo htmlspecialchars($path);?>"><button type="submit" class="btn-small btn-del">DEL</button></form><?php if($isZip):?><form method="POST" style="display:inline;flex:1;" onsubmit="return confirm('Extract <?php echo htmlspecialchars($file);?>?\nMax size: 9GB');"><input type="hidden" name="action" value="unzip"><input type="hidden" name="file" value="<?php echo htmlspecialchars($path);?>"><button type="submit" class="btn-small">UNZIP</button></form><?php endif;?><button class="btn-small" onclick="renameItem('<?php echo htmlspecialchars($path);?>','<?php echo htmlspecialchars($file);?>')">REN</button><?php else:?><button class="btn-small btn-disabled" title="Permission Denied">LOCKED</button><?php endif;?></div></div><?php }?></div><?php endif;?></div><div class="modal" id="modal"><div class="modal-content"><h3 id="modalTitle">New Item</h3><form method="POST" id="modalForm"><input type="hidden" name="action" id="modalAction"><input type="text" name="name" id="modalInput" placeholder="Name..." required autofocus><button type="submit" class="btn">CREATE</button><button type="button" class="btn btn-danger" onclick="closeModal()">CANCEL</button></form></div></div><form method="POST" id="uploadForm" style="display:none;"><input type="hidden" name="action" value="upload"><input type="file" id="fileInput2"></form><script>const dropZone=document.getElementById('dropZone');const fileInput=document.getElementById('fileInput2');const uploadForm=document.getElementById('uploadForm');const progressBar=document.getElementById('progressBar');const progressFill=document.getElementById('progressFill');const maxSize=<?php echo $uploadMaxSize;?>;dropZone.addEventListener('dragover',(e)=>{e.preventDefault();dropZone.classList.add('dragover');});dropZone.addEventListener('dragleave',()=>{dropZone.classList.remove('dragover');});dropZone.addEventListener('drop',(e)=>{e.preventDefault();dropZone.classList.remove('dragover');handleFiles(e.dataTransfer.files);});dropZone.addEventListener('click',()=>{fileInput.click();});fileInput.addEventListener('change',(e)=>{handleFiles(e.target.files);});function handleFiles(files){if(files.length>0){const file=files[0];if(file.size>maxSize){alert('File too large! Max 3GB.');return;}const formData=new FormData();formData.append('action','upload');formData.append('file',file);progressBar.style.display='block';const xhr=new XMLHttpRequest();xhr.upload.addEventListener('progress',(e)=>{if(e.lengthComputable){const pct=(e.loaded/e.total)*100;progressFill.style.width=pct+'%';}});xhr.addEventListener('load',()=>{location.reload();});xhr.addEventListener('error',()=>{alert('Upload failed');progressBar.style.display='none';});xhr.open('POST','');xhr.send(formData);}}function showModal(type){document.getElementById('modal').style.display='flex';document.getElementById('modalAction').value=type==='folder'?'mkdir':'mkfile';document.getElementById('modalTitle').textContent=type==='folder'?'Create Folder':'Create File';document.getElementById('modalInput').value='';document.getElementById('modalInput').focus();}function closeModal(){document.getElementById('modal').style.display='none';}function renameItem(path,oldName){const newName=prompt('Rename to:',oldName);if(newName&&newName!==oldName){const form=document.createElement('form');form.method='POST';form.innerHTML='<input type="hidden" name="action" value="rename"><input type="hidden" name="old" value="'+path.replace(/"/g,'&quot;')+'"><input type="hidden" name="new" value="'+newName.replace(/"/g,'&quot;')+'">';document.body.appendChild(form);form.submit();}}document.addEventListener('keydown',(e)=>{if(e.key==='Escape') closeModal();});window.onclick=function(e){if(e.target===document.getElementById('modal')) closeModal();};</script></body></html>
